"""tessaro-feeds: Vendor feed certificate pinning store."""

import hashlib
import json
import os


def fingerprint(cert_der: bytes) -> str:
    """Compute the SHA-256 fingerprint of a certificate DER blob."""
    return hashlib.sha256(cert_der).hexdigest()


class PinStore:
    """Manages pinned certificates per host."""

    _pins = {
        "feeds.tessaro.net": [
            "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"
        ]
    }

    @classmethod
    def load(cls):
        """Return the default pin store instance."""
        return cls(cls._pins)

    def __init__(self, pins: dict):
        self._pins = pins

    def matches(self, host: str, fp: str) -> bool:
        """Return True if `fp` matches any pinned fingerprint for `host`."""
        return fp in self._pins.get(host, [])
